/* VFP in the gadget engine's AArch32 builder. The gadgets are generated by
 * engine/a32_simd.py, which also documents the operand words this file
 * packs: 16-bit CpuState offsets of the registers, d first. */
#include "translator.hpp"

namespace uml::cpu::arm64::gadgets::a32::detail {

Translator::Result Translator::emit_vfp(const Instruction &in,
					const FormPlan &plan)
{
	const auto &o = in.operands;
	/* aux: bit 0 double precision, bit 2 half precision (in the low half of
	 * an S register). */
	const bool dbl = (plan.aux & 1U) != 0;
	const unsigned precision = (plan.aux & 4U) != 0 ? 2U : dbl ? 1U : 0U;
	const auto reg = [dbl](int number) noexcept {
		return dbl ? d_register(number) : s_register(number);
	};
	switch (plan.family) {
	case Family::vfp3:
		push(kVfp3[plan.sub][precision]);
		push(reg(o.d) | reg(o.n) << 16 | reg(o.m) << 32);
		return {};
	case Family::vfpmac:
		push(kVfpMac[plan.sub][precision]);
		push(reg(o.d) | reg(o.n) << 16 | reg(o.m) << 32);
		return {};
	case Family::vfp2:
		/* A conditional VMOV of S or D registers, as a select (run()
		 * opened no skip for it); anything else goes behind a skip. */
		if (select_ < 14) {
			const unsigned cond = select_;
			select_ = 14;
			if (plan.sub == kVfp2Vmov && precision < 2) {
				push(kVfpMoveSelect[precision]);
				push(reg(o.d) | reg(o.m) << 16 |
				     condition_table(cond) << 32);
				return {};
			}
			begin_instruction(cond);
		}
		push(kVfp2[plan.sub][precision]);
		push(reg(o.d) | reg(o.m) << 16);
		return {};
	case Family::vfpcmp:
		push(kVfpCmp[plan.sub][precision]);
		push(reg(o.d) | reg(o.m) << 16);
		if (in.cond == 14 && !in.in_it)
			vfp_compare_ = {words_.size(), plan.sub, precision};
		return {};
	case Family::vfpimm:
		push(dbl ? G::vfp_vmov_imm_d : G::vfp_vmov_imm_s);
		push(reg(o.d));
		push(o.imm);
		return {};
	case Family::vfpcvt:
		return emit_vfp_convert(in, plan);
	case Family::vfpcore:
		return emit_vfp_core(in, plan);
	case Family::vfpsys:
		if (plan.sub == 0) {
			if (o.t == 15) {
				/* Right after an unconditional compare: one
				 * gadget sets FPSCR.NZCV and copies it to NZCV. */
				const auto cmp = vfp_compare_;
				vfp_compare_.end = ~std::size_t{};
				if (in.cond == 14 && !in.in_it &&
				    cmp.end == words_.size() &&
				    kVfpCmpApsr[cmp.operation][cmp.precision] !=
					    G::count) {
					words_[cmp.end - 2] = gadget(
						kVfpCmpApsr[cmp.operation]
							   [cmp.precision]);
					return {false, true};
				}
				push(G::vfp_vmrs_apsr);
				return {false, true};
			}
			push(G::vfp_vmrs);
			push(core(o.t));
			return {};
		}
		push(G::vfp_vmsr);
		push(core(o.t));
		return {};
	case Family::vfpmem:
	case Family::vfpblock:
		return emit_vfp_memory(in, plan);
	default:
		return {};
	}
}

Translator::Result Translator::emit_vfp_convert(const Instruction &in,
						const FormPlan &plan)
{
	const auto &o = in.operands;
	const bool dbl = (plan.aux & 1U) != 0;
	const unsigned precision = (plan.aux & 4U) != 0 ? 2U : dbl ? 1U : 0U;
	const auto reg = [dbl](int number) noexcept {
		return dbl ? d_register(number) : s_register(number);
	};
	const unsigned sign = o.unsigned_ ? 1U : 0U;
	switch (plan.sub) {
	case 0: /* Dd = Sm */
		push(G::vfp_cvt_ds);
		push(d_register(o.d) | s_register(o.m) << 16);
		return {};
	case 1: /* Sd = Dm */
		push(G::vfp_cvt_sd);
		push(s_register(o.d) | d_register(o.m) << 16);
		return {};
	case 2: { /* an integer in Sm to a float of the destination's width */
		static constexpr G table[2][3] = {
			{G::vfp_cvt_from_s_s, G::vfp_cvt_from_s_d,
			 G::vfp_cvt_from_s_h},
			{G::vfp_cvt_from_u_s, G::vfp_cvt_from_u_d,
			 G::vfp_cvt_from_u_h}};
		push(table[sign][precision]);
		push(reg(o.d) | s_register(o.m) << 16);
		return {};
	}
	case 3: { /* a float to an integer in Sd, toward zero */
		static constexpr G table[2][3] = {
			{G::vfp_cvt_to_s_s, G::vfp_cvt_to_s_d,
			 G::vfp_cvt_to_s_h},
			{G::vfp_cvt_to_u_s, G::vfp_cvt_to_u_d,
			 G::vfp_cvt_to_u_h}};
		push(table[sign][precision]);
		push(s_register(o.d) | reg(o.m) << 16);
		return {};
	}
	case 4: { /* VCVTR: as the FPSCR rounds */
		static constexpr G table[2][3] = {
			{G::vfp_cvt_tor_s_s, G::vfp_cvt_tor_s_d,
			 G::vfp_cvt_tor_s_h},
			{G::vfp_cvt_tor_u_s, G::vfp_cvt_tor_u_d,
			 G::vfp_cvt_tor_u_h}};
		push(table[sign][precision]);
		push(s_register(o.d) | reg(o.m) << 16);
		return {};
	}
	case 5: { /* fixed point, in place */
		static constexpr G to_fixed[2][2][3] = {
			{{G::vfp_cvt_tofix_s32_s, G::vfp_cvt_tofix_s32_d,
			  G::vfp_cvt_tofix_s32_h},
			 {G::vfp_cvt_tofix_s16_s, G::vfp_cvt_tofix_s16_d,
			  G::vfp_cvt_tofix_s16_h}},
			{{G::vfp_cvt_tofix_u32_s, G::vfp_cvt_tofix_u32_d,
			  G::vfp_cvt_tofix_u32_h},
			 {G::vfp_cvt_tofix_u16_s, G::vfp_cvt_tofix_u16_d,
			  G::vfp_cvt_tofix_u16_h}}};
		static constexpr G from_fixed[2][2][3] = {
			{{G::vfp_cvt_fromfix_s32_s, G::vfp_cvt_fromfix_s32_d,
			  G::vfp_cvt_fromfix_s32_h},
			 {G::vfp_cvt_fromfix_s16_s, G::vfp_cvt_fromfix_s16_d,
			  G::vfp_cvt_fromfix_s16_h}},
			{{G::vfp_cvt_fromfix_u32_s, G::vfp_cvt_fromfix_u32_d,
			  G::vfp_cvt_fromfix_u32_h},
			 {G::vfp_cvt_fromfix_u16_s, G::vfp_cvt_fromfix_u16_d,
			  G::vfp_cvt_fromfix_u16_h}}};
		const unsigned narrow = o.size == 16 ? 1U : 0U;
		push((o.to_fixed ? to_fixed : from_fixed)[sign][narrow][precision]);
		push(reg(o.d) | static_cast<std::uint64_t>(o.frac_bits) << 16);
		return {};
	}
	default: { /* half precision, in the bottom or top half of a single */
		const std::uint64_t top = plan.aux != 0 ? 2U : 0U;
		if (o.uses_double) {
			if (o.convert_from_half) {
				push(G::vfp_cvt_dh);
				push(d_register(o.d) |
				     (s_register(o.m) + top) << 16);
			} else {
				push(G::vfp_cvt_hd);
				push((s_register(o.d) + top) |
				     d_register(o.m) << 16);
			}
			return {};
		}
		if (o.convert_from_half) {
			push(G::vfp_cvt_sh);
			push(s_register(o.d) | (s_register(o.m) + top) << 16);
		} else {
			push(G::vfp_cvt_hs);
			push((s_register(o.d) + top) | s_register(o.m) << 16);
		}
		return {};
	}
	}
}

Translator::Result Translator::emit_vfp_core(const Instruction &in,
					     const FormPlan &plan)
{
	const auto &o = in.operands;
	switch (plan.sub) {
	case 0: /* Sn = Rt */
		push(G::vfp_mov_w);
		push(s_register(o.n) | core(o.t) << 16);
		return {};
	case 1: /* Rt = Sn */
		push(G::vfp_mov_w);
		push(core(o.t) | s_register(o.n) << 16);
		return {};
	case 2: /* S[m], S[m + 1] = Rt, Rt2 */
		push(G::vfp_mov_core_pair_in);
		push(s_register(o.m) | core(o.t) << 16 | core(o.t2) << 32);
		return {};
	case 3: /* Rt, Rt2 = S[m], S[m + 1] */
		push(G::vfp_mov_core_pair_out);
		push(core(o.t) | core(o.t2) << 16 | s_register(o.m) << 32);
		return {};
	case 4: /* Dm = Rt2:Rt */
		push(G::vfp_mov_core_pair_in);
		push(d_register(o.m) | core(o.t) << 16 | core(o.t2) << 32);
		return {};
	case 5: /* Rt, Rt2 = Dm */
		push(G::vfp_mov_core_pair_out);
		push(core(o.t) | core(o.t2) << 16 | d_register(o.m) << 32);
		return {};
	case 6: { /* Dd[x] = Rt */
		const unsigned bytes = static_cast<unsigned>(o.esize) / 8U;
		const std::uint64_t lane = d_register(o.d) +
			static_cast<std::uint64_t>(o.index_value) * bytes;
		push(bytes == 1 ? G::vfp_mov_to_lane_b :
		     bytes == 2 ? G::vfp_mov_to_lane_h : G::vfp_mov_to_lane_w);
		push(lane | core(o.t) << 16);
		return {};
	}
	default: { /* Rt = Dn[x], extended */
		const unsigned bytes = static_cast<unsigned>(o.esize) / 8U;
		const std::uint64_t lane = d_register(o.n) +
			static_cast<std::uint64_t>(o.index_value) * bytes;
		const bool zero = o.unsigned_;
		push(bytes == 1 ? (zero ? G::vfp_mov_from_lane_ub :
					  G::vfp_mov_from_lane_sb) :
		     bytes == 2 ? (zero ? G::vfp_mov_from_lane_uh :
					  G::vfp_mov_from_lane_sh) :
				  G::vfp_mov_from_lane_w);
		push(core(o.t) | lane << 16);
		return {};
	}
	}
}

Translator::Result Translator::emit_vfp_memory(const Instruction &in,
					       const FormPlan &plan)
{
	const auto &o = in.operands;
	if (plan.family == Family::vfpmem) {
		const bool load = plan.sub == 0;
		const bool dbl = (plan.aux & 1U) != 0;
		const bool literal = (plan.aux & 2U) != 0;
		const bool half = (plan.aux & 4U) != 0;
		const std::uint64_t vreg =
			dbl ? d_register(o.d) : s_register(o.d);
		const auto offset = static_cast<std::uint32_t>(o.imm32);
		if (literal) {
			const std::uint32_t address = o.add ?
				pc_aligned() + offset : pc_aligned() - offset;
			push(dbl ? G::vfp_ldr_d_abs :
			     half ? G::vfp_ldr_h_abs : G::vfp_ldr_s_abs);
			push(vreg | position() | std::uint64_t{address} << 32);
			return {};
		}
		const std::uintptr_t rn = source(o.n, scratch1);
		const std::uint32_t displacement = o.add ? offset : 0U - offset;
		push(load ? (dbl ? G::vfp_ldr_d_i :
			     half ? G::vfp_ldr_h_i : G::vfp_ldr_s_i) :
			    (dbl ? G::vfp_str_d_i :
			     half ? G::vfp_str_h_i : G::vfp_str_s_i));
		push(vreg | std::uint64_t{rn} << 16 | position() |
		     std::uint64_t{displacement} << 32);
		return {};
	}
	/* VLDM, VSTM, VPUSH, VPOP and the FLDMX and FSTMX forms: the registers
	 * are consecutive in CpuState, so the transfer is a copy of
	 * 4 or 8 bytes a register. A transfer that crosses a page is the
	 * semantic library's. */
	const bool load = plan.sub == 0;
	const unsigned bytes = static_cast<unsigned>(o.regs) *
			       (o.single_regs ? 4U : 8U);
	if (bytes == 0 || bytes > 128)
		return {};
	const std::uintptr_t rn = source(o.n, scratch1);
	const auto size = static_cast<std::uint32_t>(o.imm32);
	const std::uint32_t start = o.add ? 0U : 0U - size;
	const std::uint32_t written = o.add ? size : 0U - size;
	const std::uint64_t first =
		o.single_regs ? s_register(o.d) : d_register(o.d);
	push(load ? kVfpLdm[bytes / 4U] : kVfpStm[bytes / 4U]);
	push(key_);
	push(std::uint64_t{rn} | (o.wback ? std::uint64_t{1} << 15 : 0U) |
	     std::uint64_t{start & 0xffffU} << 16 |
	     std::uint64_t{written & 0xffffU} << 32 | first << 48);
	push(library_operand(in));
	return {};
}

} // namespace uml::cpu::arm64::gadgets::a32::detail
